using System;
using System.Net;

public class URLUnshortener
{
    public static string UnshortenURL(string shortUrl)
    {
        string longUrl = string.Empty;

        try
        {
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(shortUrl);
            request.AllowAutoRedirect = false;
            HttpWebResponse response = (HttpWebResponse)request.GetResponse();
            longUrl = response.Headers[\"Location\"];

            response.Close();
        }
        catch(Exception ex)
        {
            Console.WriteLine(ex.Message);
        }

        return longUrl;
    }
}

string shortUrl = \"https://bit.ly/19BiSHW\";
string longUrl = URLUnshortener.UnshortenURL(shortUrl);
longUrl;"
}

